DECLARE @t sysname, @c sysname, @cols nvarchar(max), @sql nvarchar(max), @n int, @g uniqueidentifier, @v nvarchar(400), @ct sysname;
SET @n = ISNULL(@top, 20); IF @n > 200 SET @n = 200; IF @n < 1 SET @n = 1;
SELECT @t = TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = @table AND (TABLE_NAME LIKE 'SYS[_]SCRIPT%' OR TABLE_NAME LIKE 'VW[_]SYS[_]Script%' OR TABLE_NAME LIKE 'CLT[_]SCRIPT%' OR TABLE_NAME LIKE 'SYS[_]Kiosk%' OR TABLE_NAME LIKE 'VW[_]SYS[_]Kiosk%' OR TABLE_NAME LIKE 'SYS[_]CustomField%' OR TABLE_NAME LIKE 'SYS[_]FileRepo%' OR TABLE_NAME LIKE 'VW[_]Kiosk%' OR TABLE_NAME LIKE 'SYS[_]MultiLanguageItems%' OR TABLE_NAME LIKE 'SYS[_]CustomImages%' OR TABLE_NAME LIKE 'SYS[_]AccessControl[_]AclEntries[_]%' OR TABLE_NAME LIKE 'SYS[_]Folders%' OR TABLE_NAME LIKE 'VW[_]Folders%' OR TABLE_NAME = 'SYS_TableRelations' OR TABLE_NAME LIKE 'SYS[_]UnixClient%' OR TABLE_NAME LIKE 'VW[_]UnixClient%' OR TABLE_NAME LIKE 'CLT[_]UnixClient%' OR TABLE_NAME LIKE 'SYS[_]TestRings%' OR TABLE_NAME = 'SYS_Jobs' OR TABLE_NAME LIKE 'SYS[_]Jobs[_]Parameters%');
IF @t IS NULL BEGIN SELECT N'Tabelle nicht vorhanden oder nicht freigegeben (erlaubt: SYS_SCRIPT*, VW_SYS_Script*, CLT_SCRIPT*, SYS_Kiosk*, VW_SYS_Kiosk*, SYS_CustomField*, SYS_FileRepo*, VW_Kiosk*, SYS_MultiLanguageItems*, SYS_CustomImages*, SYS_AccessControl_AclEntries_*, SYS_Folders*, VW_Folders*, SYS_TableRelations, SYS_UnixClient*, VW_UnixClient*, CLT_UnixClient*, SYS_TestRings*, SYS_Jobs, SYS_Jobs_Parameters*)' AS Fehler; RETURN; END;
IF @column IS NOT NULL SELECT @c = COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @t AND COLUMN_NAME = @column AND NOT (@t = 'SYS_Jobs' AND COLUMN_NAME = 'JobAction')
ELSE IF @value IS NOT NULL SELECT TOP 1 @c = COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @t AND COLUMN_NAME IN ('SCRIPTID','ScriptId','SCRIPT_ID','ScriptID','Id','ID') ORDER BY CASE WHEN COLUMN_NAME LIKE '%SCRIPT%' THEN 0 ELSE 1 END;
IF @value IS NOT NULL AND @c IS NULL BEGIN SELECT N'Filterspalte nicht gefunden - mit column angeben (siehe acmp_db_columns).' AS Fehler; RETURN; END;
SET @g = TRY_CONVERT(uniqueidentifier, @value);
SET @v = CASE WHEN @g IS NOT NULL THEN N'{' + CAST(@g AS nvarchar(36)) + N'}' ELSE @value END; -- ACMP speichert GUIDs in Textspalten MIT {}
IF @c IS NOT NULL SELECT @ct = DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @t AND COLUMN_NAME = @c; -- uniqueidentifier-Spalten typgerecht vergleichen
SET @cols = STUFF((SELECT N', ' + CASE WHEN @t = 'SYS_Jobs' AND COLUMN_NAME = 'JobAction' THEN N'N''(ausgeblendet: kann gespeicherte Kennwoerter enthalten)'' AS ' + QUOTENAME(COLUMN_NAME) WHEN DATA_TYPE IN ('varbinary','image','binary','timestamp') THEN N'DATALENGTH(' + QUOTENAME(COLUMN_NAME) + N') AS ' + QUOTENAME(COLUMN_NAME + N'__bytes') WHEN DATA_TYPE = 'xml' THEN N'LEFT(CAST(' + QUOTENAME(COLUMN_NAME) + N' AS nvarchar(max)), 30000) AS ' + QUOTENAME(COLUMN_NAME) WHEN DATA_TYPE IN ('ntext','text') OR (DATA_TYPE IN ('nvarchar','varchar') AND CHARACTER_MAXIMUM_LENGTH = -1) THEN N'LEFT(CAST(' + QUOTENAME(COLUMN_NAME) + N' AS nvarchar(max)), 4000) AS ' + QUOTENAME(COLUMN_NAME) ELSE QUOTENAME(COLUMN_NAME) END FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @t ORDER BY ORDINAL_POSITION FOR XML PATH(''), TYPE).value('.', 'nvarchar(max)'), 1, 2, N'');
SET @sql = N'SELECT TOP (' + CAST(@n AS nvarchar(10)) + N') ' + @cols + N' FROM ' + QUOTENAME(@t)
  + CASE WHEN @value IS NULL THEN N'' WHEN @g IS NOT NULL AND @ct = 'uniqueidentifier' THEN N' WHERE ' + QUOTENAME(@c) + N' = @g' WHEN CHARINDEX(N'%', @v) > 0 THEN N' WHERE CAST(' + QUOTENAME(@c) + N' AS nvarchar(400)) LIKE @v' ELSE N' WHERE CAST(' + QUOTENAME(@c) + N' AS nvarchar(400)) = @v' END;
EXEC sp_executesql @sql, N'@v nvarchar(400), @g uniqueidentifier', @v = @v, @g = @g;

DECLARE @t sysname, @b sysname, @k sysname, @sql nvarchar(max), @o int, @l int, @g uniqueidentifier, @v nvarchar(400), @kt sysname;
SET @o = ISNULL(@offset, 0); IF @o < 0 SET @o = 0;
SET @l = ISNULL(@length, 8000); IF @l > 60000 SET @l = 60000; IF @l < 1 SET @l = 1;
SELECT @t = TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = @table AND (TABLE_NAME LIKE 'SYS[_]SCRIPT%' OR TABLE_NAME LIKE 'VW[_]SYS[_]Script%' OR TABLE_NAME LIKE 'CLT[_]SCRIPT%' OR TABLE_NAME LIKE 'SYS[_]Kiosk%' OR TABLE_NAME LIKE 'VW[_]SYS[_]Kiosk%' OR TABLE_NAME LIKE 'SYS[_]CustomField%' OR TABLE_NAME LIKE 'SYS[_]FileRepo%' OR TABLE_NAME LIKE 'VW[_]Kiosk%' OR TABLE_NAME LIKE 'SYS[_]MultiLanguageItems%' OR TABLE_NAME LIKE 'SYS[_]CustomImages%' OR TABLE_NAME LIKE 'SYS[_]AccessControl[_]AclEntries[_]%' OR TABLE_NAME LIKE 'SYS[_]Folders%' OR TABLE_NAME LIKE 'VW[_]Folders%' OR TABLE_NAME = 'SYS_TableRelations' OR TABLE_NAME LIKE 'SYS[_]UnixClient%' OR TABLE_NAME LIKE 'VW[_]UnixClient%' OR TABLE_NAME LIKE 'CLT[_]UnixClient%' OR TABLE_NAME LIKE 'SYS[_]TestRings%' OR TABLE_NAME = 'SYS_Jobs' OR TABLE_NAME LIKE 'SYS[_]Jobs[_]Parameters%');
IF @t IS NULL BEGIN SELECT N'Tabelle nicht vorhanden oder nicht freigegeben (erlaubt: SYS_SCRIPT*, VW_SYS_Script*, CLT_SCRIPT*, SYS_Kiosk*, VW_SYS_Kiosk*, SYS_CustomField*, SYS_FileRepo*, VW_Kiosk*, SYS_MultiLanguageItems*, SYS_CustomImages*, SYS_AccessControl_AclEntries_*, SYS_Folders*, VW_Folders*, SYS_TableRelations, SYS_UnixClient*, VW_UnixClient*, CLT_UnixClient*, SYS_TestRings*, SYS_Jobs, SYS_Jobs_Parameters*)' AS Fehler; RETURN; END;
SELECT @b = COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @t AND COLUMN_NAME = @column AND DATA_TYPE IN ('varbinary','image','binary');
IF @b IS NULL BEGIN SELECT N'Spalte nicht gefunden oder keine Binaerspalte.' AS Fehler; RETURN; END;
SELECT @k = COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @t AND COLUMN_NAME = ISNULL(@keyColumn, N'');
IF @k IS NULL SELECT TOP 1 @k = COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @t AND COLUMN_NAME IN ('SCRIPTID','ScriptId','SCRIPT_ID','ScriptID','Id','ID') ORDER BY CASE WHEN COLUMN_NAME LIKE '%SCRIPT%' THEN 0 ELSE 1 END;
IF @k IS NULL BEGIN SELECT N'Schluesselspalte nicht gefunden - keyColumn angeben.' AS Fehler; RETURN; END;
SET @g = TRY_CONVERT(uniqueidentifier, @value);
SET @v = CASE WHEN @g IS NOT NULL THEN N'{' + CAST(@g AS nvarchar(36)) + N'}' ELSE @value END; -- ACMP speichert GUIDs in Textspalten MIT {}
SELECT @kt = DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @t AND COLUMN_NAME = @k; -- uniqueidentifier-Schluessel typgerecht vergleichen
SET @sql = N'SELECT TOP (10) CAST(' + QUOTENAME(@k) + N' AS nvarchar(400)) AS Schluessel, DATALENGTH(' + QUOTENAME(@b) + N') AS BytesGesamt, @o AS Offset, CONVERT(varchar(max), CAST(SUBSTRING(' + QUOTENAME(@b) + N', @o + 1, @l) AS varbinary(max)), 2) AS Hex FROM ' + QUOTENAME(@t) + CASE WHEN @g IS NOT NULL AND @kt = 'uniqueidentifier' THEN N' WHERE ' + QUOTENAME(@k) + N' = @g' ELSE N' WHERE CAST(' + QUOTENAME(@k) + N' AS nvarchar(400)) = @v' END;
EXEC sp_executesql @sql, N'@v nvarchar(400), @g uniqueidentifier, @o int, @l int', @v = @v, @g = @g, @o = @o, @l = @l;
